package com.company.skillplatform.bundle.application;
import com.company.skillplatform.artifact.infrastructure.entity.SkillArtifactEntity;import com.company.skillplatform.artifact.infrastructure.repository.SkillArtifactRepository;import com.company.skillplatform.bundle.infrastructure.entity.*;import com.company.skillplatform.bundle.infrastructure.repository.*;import com.company.skillplatform.common.application.BusinessException;import com.company.skillplatform.compatibility.infrastructure.entity.PlatformEntity;import com.company.skillplatform.compatibility.infrastructure.repository.PlatformRepository;import com.company.skillplatform.dependency.application.DependencyService;import com.company.skillplatform.storage.domain.ObjectStoragePort;import com.company.skillplatform.user.infrastructure.repository.IamUserRepository;import com.company.skillplatform.version.infrastructure.entity.SkillVersionEntity;import com.company.skillplatform.version.infrastructure.repository.SkillVersionRepository;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import java.util.zip.*;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class BundleService{private final SkillBundleRepository bundles;private final SkillBundleItemRepository items;private final PlatformRepository platforms;private final IamUserRepository users;private final SkillVersionRepository versions;private final DependencyService deps;private final SkillArtifactRepository artifacts;private final ObjectStoragePort storage;public BundleService(SkillBundleRepository b,SkillBundleItemRepository i,PlatformRepository p,IamUserRepository u,SkillVersionRepository v,DependencyService d,SkillArtifactRepository a,ObjectStoragePort s){bundles=b;items=i;platforms=p;users=u;versions=v;deps=d;artifacts=a;storage=s;}
 @PreAuthorize("hasAuthority('skill:download')")@Transactional public BundleView create(CreateCommand c,Long actorId){PlatformEntity p=platforms.findByPlatformKey(c.platform().toUpperCase()).orElseThrow(()->bad("PLATFORM_NOT_FOUND"));LinkedHashMap<Long,SkillVersionEntity> selected=new LinkedHashMap<>();for(Long id:c.rootVersionIds()){SkillVersionEntity root=published(id);selected.put(id,root);if(c.includeDependencies()){var r=deps.resolve(id);if(!r.conflicts().isEmpty())throw bad("BUNDLE_RESOLUTION_FAILED");for(var x:r.items())versions.findAll().stream().filter(v->x.skillKey().equals(v.getSkill().getSkillKey())&&x.version().equals(v.getVersion())).findFirst().ifPresent(v->selected.put(v.getId(),v));}}String lock=hash(selected.keySet().toString()+c.platform()+c.osType());String key=hash(lock+"|bundle-v1");var old=bundles.findByBundleKey(key);if(old.isPresent())return view(old.get());SkillBundleEntity b=bundles.save(new SkillBundleEntity(key,p,c.osType(),lock,users.findById(actorId).orElseThrow()));try{ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(out)){int depth=0;for(SkillVersionEntity v:selected.values()){SkillArtifactEntity a=artifacts.findFirstByVersionIdAndPlatformPlatformKeyAndOsTypeAndStatus(v.getId(),c.platform().toUpperCase(),"ANY","AVAILABLE").orElseThrow(()->bad("BUNDLE_RESOLUTION_FAILED"));zip.putNextEntry(new ZipEntry(v.getSkill().getSkillKey()+"/"+a.getFileName()));try(InputStream in=storage.get(a.getObjectKey())){in.transferTo(zip);}zip.closeEntry();items.save(new SkillBundleItemEntity(b,v,a,c.rootVersionIds().contains(v.getId()),depth++,v.getSkill().getSkillKey()));}}byte[] bytes=out.toByteArray();String object="bundles/"+key+".zip";storage.put(object,new ByteArrayInputStream(bytes),bytes.length,"application/zip");b.available(object,bytes.length,hashBytes(bytes));bundles.save(b);return view(b);}catch(IOException e){throw bad("BUNDLE_BUILD_FAILED");}}
 private SkillVersionEntity published(Long id){SkillVersionEntity v=versions.findById(id).orElseThrow(()->bad("SKILL_VERSION_NOT_FOUND"));if(v.getVersion()==null||!(v.getLifecycleStatus().name().equals("PUBLISHED")||v.getLifecycleStatus().name().equals("DEPRECATED")))throw bad("BUNDLE_RESOLUTION_FAILED");return v;}private String hash(String s){return hashBytes(s.getBytes(StandardCharsets.UTF_8));}private String hashBytes(byte[] b){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}catch(Exception e){throw new IllegalStateException(e);}}private BusinessException bad(String c){return new BusinessException(c,c,HttpStatus.UNPROCESSABLE_ENTITY);}private BundleView view(SkillBundleEntity b){return new BundleView(b.getId(),b.getBundleKey(),b.getStatus(),b.getFileName(),b.getSizeBytes(),b.getSha256());}public record CreateCommand(String platform,String osType,List<Long> rootVersionIds,boolean includeDependencies){}public record BundleView(Long id,String bundleKey,String status,String fileName,Long sizeBytes,String sha256){}
 @PreAuthorize("hasAuthority('skill:download')")@Transactional(readOnly=true)public BundleView get(Long id){return view(bundles.findById(id).orElseThrow(()->bad("BUNDLE_NOT_FOUND")));}
 @Transactional public void retryBuild(Long id){SkillBundleEntity b=bundles.findById(id).orElseThrow(()->bad("BUNDLE_NOT_FOUND"));try{ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(out)){for(SkillBundleItemEntity item:items.findByBundleId(id)){SkillArtifactEntity a=item.getArtifact();zip.putNextEntry(new ZipEntry(item.getVersion().getSkill().getSkillKey()+"/"+a.getFileName()));try(InputStream in=storage.get(a.getObjectKey())){in.transferTo(zip);}zip.closeEntry();}}byte[] bytes=out.toByteArray();String object="bundles/"+b.getBundleKey()+".zip";storage.put(object,new ByteArrayInputStream(bytes),bytes.length,"application/zip");b.available(object,bytes.length,hashBytes(bytes));bundles.save(b);}catch(Exception ex){b.failed("BUNDLE_RETRY_FAILED",ex.getMessage()==null?"Bundle retry failed":ex.getMessage().substring(0,Math.min(1024,ex.getMessage().length())));bundles.save(b);}}
}
